; Mode text, counter, energy bars and scores
; $827f-$8309

; Shows DEMO in the demo. Else shows 1PLR or 2PLR.
show_mode_text
        lda demo_mode
        beq show_mode_text_players
        lda #$84                        ; Text $84: DEMO.
        jmp show_mode_text_print
show_mode_text_players
        lda two_players
        clc
        adc #$82                        ; Text $82 or $83: 1PLR or 2PLR.
show_mode_text_print
        jsr print_text
        rts
; Writes the 2-digit number of text $86 and shows it. Two-player game: the time left. Else: the opponent number.
show_counter
        lda #$86
        asl
        tay
        lda text_ptrs,y
        sta text_ptr
        lda text_ptrs+1,y
        sta text_ptr+1
        lda demo_mode
        bne show_counter_opponent
        lda two_players
        beq show_counter_opponent
        ldy #$03                        ; Converts time_left to two decimal digits.
        ldx #$ff
        lda time_left
show_counter_time_loop
        sta cur_fighter
        inx
        sec
        sbc #$0a
        bpl show_counter_time_loop
        txa
        ora #$30
        sta (text_ptr),y
        iny
        lda cur_fighter
        ora #$30
        sta (text_ptr),y
        jmp show_counter_print
show_counter_opponent
        ldy #$03
        lda #$30
        sta (text_ptr),y
        lda opponent_index
        ora #$30
        iny
        sta (text_ptr),y
show_counter_print
        lda #$86
        jsr print_text
        rts
; Shows the energy bar and the score of each fighter. The texts $8b-$97 are the bars for energy 0-12.
show_energy_scores
        ldx #$01
show_energy_scores_loop
        stx cur_fighter
        lda fighter_energy,x
        clc
        adc #$8b
        pha
        asl
        tay
        lda text_ptrs,y
        sta text_ptr
        lda text_ptrs+1,y
        sta text_ptr+1
        ldy #$00
        lda energy_text_columns,x       ; Column of the bar: 0 for fighter 0, 34 for fighter 1. The bar has 2 rows.
        sta (text_ptr),y
        ldy #$0a
        sta (text_ptr),y
        pla
        jsr print_text
        lda cur_fighter
        clc
        adc #$87                        ; Text $87 or $88: the score of the fighter.
        jsr print_text
        ldx cur_fighter
        dex
        bpl show_energy_scores_loop
        rts
